package org.efootballrevival.runtimeprobe;
import android.app.*;import android.content.*;import android.graphics.Color;import android.text.*;import android.widget.*;import org.json.*;import java.util.Locale;
public final class SkinColourEditor{
 private static String manage(Activity a,JSONObject req)throws Exception{return(String)Class.forName("org.efootballrevival.runtimeprobe.EmbeddedGateway").getMethod("manage",Context.class,String.class,String.class).invoke(null,a,"ui78_appearance_apply",req.toString());}
 private static void error(Activity a,Exception e){if(!a.isFinishing())new AlertDialog.Builder(a).setTitle("Body Colour").setMessage(String.valueOf(e.getCause()==null?e.getMessage():e.getCause().getMessage())).setPositiveButton("Close",null).show();}
 public static void form(Activity a,JSONObject player,JSONObject data){LinearLayout col=new LinearLayout(a);col.setOrientation(1);int pad=Math.round(16*a.getResources().getDisplayMetrics().density);col.setPadding(pad,pad,pad,pad);col.setBackgroundColor(0xff101f38);col.setFocusableInTouchMode(true);col.requestFocus();ScrollView scroll=new ScrollView(a);scroll.addView(col);
 TextView note=new TextView(a);note.setText("Choose a game skin tone or your own RGB colour for the body. Face textures keep their own colours. Save before Enter Game, then reopen the app. Palette previews show the game texture colours; match lighting will vary.");note.setTextColor(0xffc9dfee);col.addView(note);
 Spinner mode=new Spinner(a);String[] modes={"Original","Game palette1","Game palette2","Game palette3","Game palette4","Game palette5","Game palette6","Custom RGB"};ArrayAdapter<String> adapter=new ArrayAdapter<>(a,android.R.layout.simple_spinner_item,modes);adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);mode.setAdapter(adapter);col.addView(mode,new LinearLayout.LayoutParams(-1,-2));String current=data.isNull("rgb")?"":data.optString("rgb","");mode.setSelection(current.matches("[0-9a-fA-F]{6}")?7:data.optInt("skin",0));
 TextView paletteTitle=new TextView(a);paletteTitle.setText("Game palettes · colour previews");paletteTitle.setTextColor(0xffe4efff);col.addView(paletteTitle);JSONArray previews=data.optJSONArray("skin_previews");if(previews!=null){for(int row=0;row<2;row++){LinearLayout line=new LinearLayout(a);line.setOrientation(0);for(int j=0;j<3;j++){JSONObject item=previews.optJSONObject(row*3+j);if(item==null)continue;int choice=item.optInt("id");String colour=item.optString("hex","ae8975");Button b=new Button(a);b.setText("Palette "+choice);b.setAllCaps(false);b.setTextSize(12);b.setTextColor(choice<5?Color.BLACK:Color.WHITE);b.setBackgroundColor(0xff000000|Integer.parseInt(colour,16));b.setOnClickListener(v->mode.setSelection(choice));line.addView(b,new LinearLayout.LayoutParams(0,-2,1));}col.addView(line,new LinearLayout.LayoutParams(-1,-2));}}
 TextView label=new TextView(a);label.setText("Custom colour · #RRGGBB");label.setTextColor(0xffe4efff);col.addView(label);EditText hex=new EditText(a);hex.setSingleLine(true);hex.setTextColor(0xfff5fbff);hex.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS);hex.setFilters(new InputFilter[]{new InputFilter.LengthFilter(7)});col.addView(hex,new LinearLayout.LayoutParams(-1,-2));TextView swatch=new TextView(a);swatch.setMinHeight(pad*4);swatch.setGravity(17);swatch.setTextSize(16);col.addView(swatch,new LinearLayout.LayoutParams(-1,-2));SeekBar[] channels=new SeekBar[3];String[] names={"R","G","B"};for(int i=0;i<3;i++){TextView t=new TextView(a);t.setText(names[i]);t.setTextColor(0xffd3eaff);col.addView(t);channels[i]=new SeekBar(a);channels[i].setMax(255);col.addView(channels[i],new LinearLayout.LayoutParams(-1,-2));}
 final boolean[] changing={false};Runnable paint=()->{String text=hex.getText().toString().trim().replace("#","");if(!text.matches("[0-9a-fA-F]{6}")){swatch.setText("Enter6 hex digits");return;}int value=Integer.parseInt(text,16);swatch.setBackgroundColor(0xff000000|value);int r=value>>16,g=(value>>8)&255,b=value&255;swatch.setTextColor((r*54+g*183+b*19)>128*256?Color.BLACK:Color.WHITE);swatch.setText("#"+text.toUpperCase(Locale.US)+"   RGB "+r+", "+g+", "+b);changing[0]=true;channels[0].setProgress(r);channels[1].setProgress(g);channels[2].setProgress(b);changing[0]=false;};hex.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void onTextChanged(CharSequence s,int st,int before,int count){if(!changing[0]){if(hex.hasFocus())mode.setSelection(7);paint.run();}}public void afterTextChanged(Editable e){}});
 for(SeekBar channel:channels)channel.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}public void onProgressChanged(SeekBar s,int p,boolean fromUser){if(!fromUser||changing[0])return;mode.setSelection(7);hex.setText(String.format(Locale.US,"%02x%02x%02x",channels[0].getProgress(),channels[1].getProgress(),channels[2].getProgress()));}});
 String[] colours={"f1c7a5","d8a373","b77b50","927557","5b3a29","4e5b37"};String[] titles={"Light","Warm","Medium","Olive","Dark","Hulk"};for(int row=0;row<2;row++){LinearLayout line=new LinearLayout(a);line.setOrientation(0);for(int j=0;j<3;j++){int k=row*3+j;Button b=new Button(a);int value=Integer.parseInt(colours[k],16);b.setText(titles[k]+"\n#"+colours[k].toUpperCase(Locale.US));b.setTextSize(11);b.setAllCaps(false);b.setBackgroundColor(0xff000000|value);b.setTextColor(k<3?Color.BLACK:Color.WHITE);b.setOnClickListener(v->{mode.setSelection(7);hex.setText(colours[k]);});line.addView(b,new LinearLayout.LayoutParams(0,-2,1));}col.addView(line,new LinearLayout.LayoutParams(-1,-2));}hex.setText(current.matches("[0-9a-fA-F]{6}")?current:"c68642");paint.run();
 AlertDialog d=new AlertDialog.Builder(a).setTitle("Body Colour · RGB").setView(scroll).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();d.show();ResponsiveUi.fit(a,d);d.getButton(-1).setOnClickListener(v->{try{int m=mode.getSelectedItemPosition();JSONObject values=new JSONObject().put("59",data.optInt("59")).put("60",data.optInt("60"));if(m==7){String text=hex.getText().toString().trim().replace("#","");if(!text.matches("[0-9a-fA-F]{6}"))throw new Exception("Enter a valid6-digit RGB colour");values.put("rgb",text.toLowerCase(Locale.US));}else{values.put("rgb",JSONObject.NULL);if(m>0)values.put("skin",m);}JSONObject req=new JSONObject(player.toString()).put("values",values);d.getButton(-1).setEnabled(false);new Thread(()->{try{JSONObject result=new JSONObject(manage(a,req));if(!result.optBoolean("saved"))throw new Exception("Save was not confirmed");a.runOnUiThread(()->{d.dismiss();Toast.makeText(a,"Colour saved. Reopen the app before entering a match.",Toast.LENGTH_LONG).show();});}catch(Exception e){a.runOnUiThread(()->{d.getButton(-1).setEnabled(true);error(a,e);});}},"PrepareBodyColour").start();}catch(Exception e){error(a,e);}});
 }
}
